extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve essere impostata e avviarsi senza errori"):
		return
	var sprite := find_by_name(main, "Sprite2D") as Sprite2D
	if not check("sprite", sprite != null, "Nella scena deve esserci un nodo Sprite2D"):
		return
	check("sprite_texture", sprite.texture != null, "Al nodo Sprite2D deve essere assegnata una texture")
	check("sprite_pos", abs(sprite.position.x - 200.0) < 5.0 and abs(sprite.position.y - 300.0) < 5.0, "La posizione di Sprite2D deve essere vicina a (200, 300)")
	var label := find_by_name(main, "Label") as Label
	if not check("label", label != null, "Nella scena deve esserci un nodo Label"):
		return
	check("label_text", label.text == "Benvenuto in Godot!", "Il testo del nodo Label deve essere 'Benvenuto in Godot!'")
	check("label_pos", abs(label.position.x - 350.0) < 5.0 and abs(label.position.y - 150.0) < 5.0, "La posizione del nodo Label deve essere vicina a (350, 150)")
